// 新profile只增加原撤职来源强验；旧无模块世界不增空尾或忽略旧回执。
#include "political_dismissal_profile.hpp"
namespace hanmo::resident {
Outcome<Integer> political_dismissal_source_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer version=0;for(const auto& m:modules)if(m.first==political_dismissal_sources_module){if(m.second!="1"||version++)return {false,0,common_failure("PoliticalDismissalSourceModuleMismatch").error};}if(!version)return {true,0,{}};for(const auto* name:{"politics","family_life"}){Integer count=0;for(const auto& m:modules)if(m.first==name){if(m.second!="1"||++count!=1)return {false,0,common_failure("PoliticalDismissalOriginalProfileRequired").error};}if(count!=1)return {false,0,common_failure("PoliticalDismissalOriginalProfileRequired").error};}return {true,1,{}};}
Outcome<std::optional<PoliticalDismissalSourceCatalog>> decode_political_dismissal_source_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* d=scenario.find("dynamic_world");const auto* group=d?d->find(political_dismissal_sources_module):nullptr;if(!group)return {true,std::nullopt,{}};const auto* politics=d?d->find("politics"):nullptr;const auto* enabled=politics?politics->find("enabled"):nullptr;const auto* family=scenario.find("family_life");const auto* profile=family?family->find("profile"):nullptr;if(!enabled||!std::holds_alternative<bool>(enabled->data)||!std::get<bool>(enabled->data)||!profile||!std::holds_alternative<std::string>(profile->data)||std::get<std::string>(profile->data)!="verified_military_deaths_v1"||std::find(caps.begin(),caps.end(),"family_life_v1")==caps.end())return {false,{},common_failure("PoliticalDismissalOriginalProfileRequired").error};if(std::find(caps.begin(),caps.end(),"political_dismissal_sources_v1")==caps.end())return {false,{},common_failure("PoliticalDismissalSourceCapabilityRequired").error};auto out=decode_political_dismissal_source_catalog(*group);return out.ok?Outcome<std::optional<PoliticalDismissalSourceCatalog>>{true,std::move(out.value),{}}:Outcome<std::optional<PoliticalDismissalSourceCatalog>>{false,{},out.error};}
Status validate_political_dismissal_source_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalDismissalSourceState* state){auto selected=political_dismissal_source_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(state)!=(selected.value==1)||(state&&state->version!=1))return common_failure("PoliticalDismissalSourceProfileMismatch");for(const auto& row:c.state().facts.rows())if(row.second.domain==political_dismissal_sources_module)return common_failure("PoliticalDismissalUnexpectedCommonFact",row.first);return state?validate_political_dismissal_state_layout(*state):common_success();}
}
